async () => {
  const ids = ['8553538/TECH-9053','8553538/TECH-9060','8553538/TECH-9055','8553538/TECH-9051'];
  const out = [];
  for (const id of ids) {
    try {
      const res = await fetch('https://app.clickup.com/t/' + id, { credentials: 'include', redirect: 'follow' });
      out.push({ id, status: res.status, url: res.url, title: undefined });
    } catch (e) {
      out.push({ id, error: String(e) });
    }
  }
  const html = document.title;
  return { pageTitle: html, pageUrl: location.href, fetches: out };
}

