const ts = require('/Users/stark/Desktop/work/RN/circleapp/node_modules/typescript');
const path = require('path');
const fs = require('fs');

const root = '/Users/stark/Desktop/work/RN/circleapp';
const configPath = path.join(root, 'tsconfig.json');
const configFile = ts.readConfigFile(configPath, ts.sys.readFile);
if (configFile.error) {
  console.error('readConfigFile', ts.flattenDiagnosticMessageText(configFile.error.messageText, '\n'));
  process.exit(1);
}
const parsed = ts.parseJsonConfigFileContent(configFile.config, ts.sys, root, undefined, configPath);
console.log('parseErrors', parsed.errors.length);
if (parsed.errors.length) {
  for (const e of parsed.errors.slice(0, 20)) {
    console.log(ts.flattenDiagnosticMessageText(e.messageText, '\n'), e.code);
  }
}

const changedRel = [
  'src/i18n/locale/Indonesia.ts',
  'src/i18n/locale/Melayu.ts',
  'src/i18n/locale/zh.ts',
  'src/i18n/locale/zh_tw.ts',
  'src/screens/doctor-detail-screen/doctor-detail-screen.tsx',
  'src/screens/home/home-screen/home-screen.tsx',
  'src/screens/my-appointment-list-screen/my-appointment-list-screen.tsx',
  'src/screens/my-appointment-screen/my-appointment-screen.tsx',
];
const changedAbs = changedRel.map((p) => path.join(root, p));

const program = ts.createProgram({
  rootNames: parsed.fileNames,
  options: parsed.options,
});
const allFiles = program.getSourceFiles().map((sf) => sf.fileName);
console.log('programFiles', allFiles.length);

function fmtDiag(d, sf) {
  const file = d.file || sf;
  let loc = '';
  if (file && typeof d.start === 'number') {
    const pos = file.getLineAndCharacterOfPosition(d.start);
    loc = `${path.relative(root, file.fileName)}:${pos.line + 1}:${pos.character + 1}`;
  }
  const category = ts.DiagnosticCategory[d.category];
  return {
    loc,
    code: d.code,
    category,
    message: ts.flattenDiagnosticMessageText(d.messageText, '\n'),
  };
}

const result = {};
for (const abs of changedAbs) {
  const sf = program.getSourceFile(abs);
  const rel = path.relative(root, abs);
  if (!sf) {
    result[rel] = { missingInProgram: true };
    continue;
  }
  const syntactic = program.getSyntacticDiagnostics(sf);
  const semantic = program.getSemanticDiagnostics(sf);
  const suggestion = program.getSuggestionDiagnostics(sf);
  result[rel] = {
    inProgram: true,
    syntactic: syntactic.map((d) => fmtDiag(d, sf)),
    semantic: semantic.map((d) => fmtDiag(d, sf)),
    suggestion: suggestion.map((d) => fmtDiag(d, sf)),
  };
}

console.log(JSON.stringify(result, null, 2));
EOF
